'AC4.14.13 AC4.14.14'; from datetime import date; from decimal import Decimal; from common.testing.ac_proof import ac_proof; from sqlalchemy import select; from sqlalchemy.ext.asyncio import AsyncSession; from src.audit import JournalEntrySourceType; from src.ledger import Account, AccountType, Direction, JournalEntry, JournalEntryStatus, JournalLine; from src.pricing import FxConversion; from src.pricing.orm.market_data import FxRate; from src.reporting import generate_balance_sheet, generate_income_statement; _OUT_SGD = Decimal('1360.00'); _IN_USD = Decimal('1000.00'); _RATE_SGD_PER_USD = Decimal('1.360000'); _SALARY_SGD = Decimal('5000.00'); _FEE_SGD = Decimal('2.50'); _REPORT_DATE = date(2025, 6, 30); _PERIOD_START = date(2025, 6, 1); _TXN_DATE = date(2025, 6, 15)
async def _account(db, user_id, *, name, account_type, currency='SGD') -> Account: account = Account(user_id=user_id, name=name, type=account_type, currency=currency); db.add(account); await db.flush(); return account
async def _post_entry(db, user_id, *, debit_account, credit_account, amount, currency) -> JournalEntry: entry = JournalEntry(user_id=user_id, entry_date=_TXN_DATE, memo='seed', source_type=JournalEntrySourceType.MANUAL, status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); line_fx_rate = None if currency.upper() == 'SGD' else _RATE_SGD_PER_USD; db.add_all([JournalLine(journal_entry_id=entry.id, account_id=debit_account.id, direction=Direction.DEBIT, amount=amount, currency=currency, fx_rate=line_fx_rate), JournalLine(journal_entry_id=entry.id, account_id=credit_account.id, direction=Direction.CREDIT, amount=amount, currency=currency, fx_rate=line_fx_rate)]); await db.flush(); return entry
async def _seed_fx_rate(db) -> None: db.add(FxRate(base_currency='USD', quote_currency='SGD', rate=_RATE_SGD_PER_USD, rate_date=_TXN_DATE, source='test')); db.add(FxRate(base_currency='SGD', quote_currency='USD', rate=(Decimal('1') / _RATE_SGD_PER_USD).quantize(Decimal('0.000001')), rate_date=_TXN_DATE, source='test'))
async def _seed_raw_ledger_transfer(db: AsyncSession, user_id) -> None: await _seed_fx_rate(db); sgd_bank = await _account(db, user_id, name='SGD Bank', account_type=AccountType.ASSET, currency='SGD'); usd_bank = await _account(db, user_id, name='USD Bank', account_type=AccountType.ASSET, currency='USD'); salary_income = await _account(db, user_id, name='Salary', account_type=AccountType.INCOME, currency='SGD'); transfer_income = await _account(db, user_id, name='Misclassified Transfer In', account_type=AccountType.INCOME, currency='USD'); transfer_expense = await _account(db, user_id, name='Misclassified Transfer Out', account_type=AccountType.EXPENSE, currency='SGD'); await _post_entry(db, user_id, debit_account=sgd_bank, credit_account=salary_income, amount=_SALARY_SGD, currency='SGD'); await _post_entry(db, user_id, debit_account=usd_bank, credit_account=transfer_income, amount=_IN_USD, currency='USD'); await _post_entry(db, user_id, debit_account=transfer_expense, credit_account=sgd_bank, amount=_OUT_SGD, currency='SGD'); await db.commit()
@ac_proof('fx-ledger-autodiscovery-income-statement-e2e', ac_ids=['AC-reconciliation.fx-transfer.13'], scope='behavioral', ci_tier='pr_ci', trust_mode='deterministic_pr', source_classes=['manual_record'], issue='#1123')
async def test_AC2_raw_ledger_internal_transfer_autodiscovered_e2e(db: AsyncSession, test_user): 'AC-reconciliation.fx-transfer.13 AC4.14.13'; await _seed_raw_ledger_transfer(db, test_user.id); recorded = (await db.execute(select(FxConversion).where(FxConversion.user_id == test_user.id))).scalars().all(); assert recorded == [], 'scenario must rely on auto-discovery, not a recorded fx_conversions row'; report = await generate_income_statement(db, test_user.id, start_date=_PERIOD_START, end_date=_REPORT_DATE, currency='SGD'); assert report['total_income'] == _SALARY_SGD; assert report['total_expenses'] == Decimal('0.00'); assert report['net_income'] == _SALARY_SGD; balance_sheet = await generate_balance_sheet(db, test_user.id, as_of_date=_REPORT_DATE, currency='SGD', include_trust_signals=False); assert balance_sheet['net_income'] == _SALARY_SGD
@ac_proof('fx-ledger-autodiscovery-roundtrip-pnl-e2e', ac_ids=['AC-reconciliation.fx-transfer.14'], scope='behavioral', ci_tier='pr_ci', trust_mode='deterministic_pr', source_classes=['manual_record'], issue='#1123')
async def test_AC4_same_day_round_trip_nets_zero_pnl_through_live_report(db: AsyncSession, test_user): 'AC-reconciliation.fx-transfer.14 AC4.14.14'; await _seed_fx_rate(db); sgd_bank = await _account(db, test_user.id, name='SGD Bank', account_type=AccountType.ASSET, currency='SGD'); usd_bank = await _account(db, test_user.id, name='USD Bank', account_type=AccountType.ASSET, currency='USD'); transfer_income_usd = await _account(db, test_user.id, name='Transfer In USD', account_type=AccountType.INCOME, currency='USD'); transfer_expense_sgd = await _account(db, test_user.id, name='Transfer Out SGD', account_type=AccountType.EXPENSE, currency='SGD'); transfer_income_sgd = await _account(db, test_user.id, name='Transfer In SGD', account_type=AccountType.INCOME, currency='SGD'); transfer_expense_usd = await _account(db, test_user.id, name='Transfer Out USD', account_type=AccountType.EXPENSE, currency='USD'); await _post_entry(db, test_user.id, debit_account=transfer_expense_sgd, credit_account=sgd_bank, amount=_OUT_SGD, currency='SGD'); await _post_entry(db, test_user.id, debit_account=usd_bank, credit_account=transfer_income_usd, amount=_IN_USD, currency='USD'); await _post_entry(db, test_user.id, debit_account=transfer_expense_usd, credit_account=usd_bank, amount=_IN_USD, currency='USD'); await _post_entry(db, test_user.id, debit_account=sgd_bank, credit_account=transfer_income_sgd, amount=_OUT_SGD, currency='SGD'); await db.commit(); report = await generate_income_statement(db, test_user.id, start_date=_PERIOD_START, end_date=_REPORT_DATE, currency='SGD'); assert report['total_income'] == Decimal('0.00'); assert report['total_expenses'] == Decimal('0.00'); assert report['net_income'] == Decimal('0.00')
async def _seed_internal_transfer_scenario(db: AsyncSession, user_id) -> None: db.add(FxRate(base_currency='USD', quote_currency='SGD', rate=_RATE_SGD_PER_USD, rate_date=_TXN_DATE, source='test')); sgd_bank = await _account(db, user_id, name='SGD Bank', account_type=AccountType.ASSET, currency='SGD'); usd_bank = await _account(db, user_id, name='USD Bank', account_type=AccountType.ASSET, currency='USD'); salary_income = await _account(db, user_id, name='Salary', account_type=AccountType.INCOME, currency='SGD'); transfer_income = await _account(db, user_id, name='Misclassified Transfer In', account_type=AccountType.INCOME, currency='USD'); transfer_expense = await _account(db, user_id, name='Misclassified Transfer Out', account_type=AccountType.EXPENSE, currency='SGD'); await _post_entry(db, user_id, debit_account=sgd_bank, credit_account=salary_income, amount=_SALARY_SGD, currency='SGD'); in_entry = await _post_entry(db, user_id, debit_account=usd_bank, credit_account=transfer_income, amount=_IN_USD, currency='USD'); out_entry = await _post_entry(db, user_id, debit_account=transfer_expense, credit_account=sgd_bank, amount=_OUT_SGD, currency='SGD'); db.add(FxConversion(user_id=user_id, from_account_id=sgd_bank.id, to_account_id=usd_bank.id, amount_from=_OUT_SGD, currency_from='SGD', amount_to=_IN_USD, currency_to='USD', rate=_RATE_SGD_PER_USD, fee=_FEE_SGD, fee_currency='SGD', conversion_date=_TXN_DATE, from_journal_entry_id=out_entry.id, to_journal_entry_id=in_entry.id)); await db.commit()
@ac_proof('internal-transfer-income-statement-e2e', ac_ids=['AC-reconciliation.fx-transfer.9'], scope='behavioral', ci_tier='pr_ci', trust_mode='deterministic_pr', source_classes=['manual_record'], issue='#1123')
async def test_AC3_internal_transfer_excluded_from_income_statement_e2e(db: AsyncSession, test_user): 'AC-reconciliation.fx-transfer.9'; await _seed_internal_transfer_scenario(db, test_user.id); report = await generate_income_statement(db, test_user.id, start_date=_PERIOD_START, end_date=_REPORT_DATE, currency='SGD'); assert report['total_income'] == _SALARY_SGD; assert report['total_expenses'] == _FEE_SGD; assert report['net_income'] == Decimal('4997.50'); expense_lines = report['expenses']; expense_line_sum = sum((Decimal(str(line['amount'])) for line in expense_lines), Decimal('0')); assert expense_line_sum == report['total_expenses']; fee_lines = [line for line in expense_lines if Decimal(str(line['amount'])) == _FEE_SGD]; assert len(fee_lines) == 1, 'internal-transfer fee must appear as a single expense line'; assert fee_lines[0]['account_id'] is not None; assert sum((Decimal(str(t['total_expenses'])) for t in report['trends']), Decimal('0')) == _FEE_SGD
@ac_proof('internal-transfer-balance-sheet-net-income-e2e', ac_ids=['AC-reconciliation.fx-transfer.10'], scope='behavioral', ci_tier='pr_ci', trust_mode='deterministic_pr', source_classes=['manual_record'], issue='#1123')
async def test_AC3_internal_transfer_net_income_fee_only_e2e(db: AsyncSession, test_user): 'AC-reconciliation.fx-transfer.10'; await _seed_internal_transfer_scenario(db, test_user.id); report = await generate_balance_sheet(db, test_user.id, as_of_date=_REPORT_DATE, currency='SGD', include_trust_signals=False); assert report['net_income'] == Decimal('4997.50')
